<?php
namespace App\Services;
use App\Models\User;use App\Support\Decimal;use Illuminate\Support\Facades\DB;use RuntimeException;
class PaperTradingService {
public function __construct(private LedgerService $ledger,private MarketQuoteService $markets){}
public function open(User $u,string $symbol,string $direction,string $stake,int $duration,string $key):int{
if(!config('shell.paper.enabled'))throw new RuntimeException('Paper trading is disabled.');if(!in_array($symbol,config('shell.market.symbols',[]),true))throw new RuntimeException('Unsupported pair.');if(!in_array($direction,['UP','DOWN'],true))throw new RuntimeException('Invalid direction.');if(!in_array($duration,config('shell.paper.durations',[]),true))throw new RuntimeException('Invalid duration.');$amount=Decimal::units($stake);if($amount<=0||$amount>Decimal::units((string)config('shell.paper.max_stake')))throw new RuntimeException('Stake is outside paper limits.');$quote=$this->markets->freshQuote($symbol);$currency=config('shell.paper.currency','USDT');
return DB::transaction(function()use($u,$symbol,$direction,$stake,$duration,$key,$quote,$currency){$old=DB::table('paper_trades')->where('open_idempotency_key',$key)->first();if($old){if((int)$old->user_id!==$u->id)throw new RuntimeException('Request key already used.');return (int)$old->id;}$wallet=$this->ledger->wallet($u,$currency);DB::table('ledger_accounts')->where('id',$wallet)->lockForUpdate()->first();if($this->ledger->balanceUnits($wallet)<Decimal::units($stake))throw new RuntimeException('Insufficient paper balance. Ask an administrator to issue simulation credits.');$escrow=$this->ledger->system('PAPER_ESCROW',$currency);$this->ledger->post('paper-open:'.$key,'Paper trade stake reserved',[['account_id'=>$wallet,'side'=>'debit','amount'=>$stake],['account_id'=>$escrow,'side'=>'credit','amount'=>$stake]],['user_id'=>$u->id,'symbol'=>$symbol,'environment'=>'paper']);return (int)DB::table('paper_trades')->insertGetId(['user_id'=>$u->id,'symbol'=>$symbol,'direction'=>$direction,'stake'=>$stake,'opening_price'=>$quote->price,'duration_seconds'=>$duration,'status'=>'open','open_idempotency_key'=>$key,'opened_at'=>now(),'expires_at'=>now()->addSeconds($duration),'created_at'=>now(),'updated_at'=>now()]);});
}
public function settleDue():int{$trades=DB::table('paper_trades')->where('status','open')->where('expires_at','<=',now())->limit(500)->get();$count=0;foreach($trades as $trade){$q=DB::table('market_quotes')->where('symbol',$trade->symbol)->first();if(!$q||$q->captured_at<$trade->expires_at||now()->diffInSeconds($q->captured_at)>(int)config('shell.market.max_age_seconds',90))continue;DB::transaction(function()use($trade,$q,&$count){$t=DB::table('paper_trades')->where('id',$trade->id)->lockForUpdate()->first();if(!$t||$t->status!=='open')return;$cmp=Decimal::compare((string)$q->price,(string)$t->opening_price);$won=($t->direction==='UP'&&$cmp>0)||($t->direction==='DOWN'&&$cmp<0);$tie=$cmp===0;$c=config('shell.paper.currency','USDT');$wallet=$this->ledger->wallet(User::findOrFail($t->user_id),$c);$escrow=$this->ledger->system('PAPER_ESCROW',$c);$entries=[['account_id'=>$escrow,'side'=>'debit','amount'=>$t->stake]];
if($tie){$entries[]=['account_id'=>$wallet,'side'=>'credit','amount'=>$t->stake];$status='void';}
elseif($won){$payout=Decimal::multiplyRatio((string)$t->stake,(int)config('shell.paper.payout_basis_points',18000),10000);$profit=Decimal::fromUnits(Decimal::units($payout)-Decimal::units((string)$t->stake));$reward=$this->ledger->system('PAPER_REWARDS',$c,'debit');$entries[]=['account_id'=>$reward,'side'=>'debit','amount'=>$profit];$entries[]=['account_id'=>$wallet,'side'=>'credit','amount'=>$payout];$status='won';}
else{$revenue=$this->ledger->system('PAPER_REVENUE',$c);$entries[]=['account_id'=>$revenue,'side'=>'credit','amount'=>$t->stake];$status='lost';}
$key='paper-settle:'.$t->id;$this->ledger->post($key,'Paper trade settlement',$entries,['trade_id'=>$t->id,'outcome'=>$status,'environment'=>'paper']);DB::table('paper_trades')->where('id',$t->id)->update(['closing_price'=>$q->price,'status'=>$status,'settlement_idempotency_key'=>$key,'settled_at'=>now(),'updated_at'=>now()]);$count++;});}return $count;}
}
